80: int spiffsTryMount()
81: {
82:     spiffs_config cfg = {0};
83: 
84:     cfg.phys_addr = 0x0000;
85:     cfg.phys_size = (u32_t) s_flashmem.size();
86: 
87:     cfg.phys_erase_block = s_blockSize;
88:     cfg.log_block_size = s_blockSize;
89:     cfg.log_page_size = s_pageSize;
90: 
91:     cfg.hal_read_f = api_spiffs_read;
92:     cfg.hal_write_f = api_spiffs_write;
93:     cfg.hal_erase_f = api_spiffs_erase;
94: 
95:     const int maxOpenFiles = 4;
96:     s_spiffsWorkBuf.resize(s_pageSize * 2);
97:     s_spiffsFds.resize(32 * maxOpenFiles);
98:     s_spiffsCache.resize((32 + s_pageSize) * maxOpenFiles);
99: 
100:     return SPIFFS_mount(&s_fs, &cfg,
101:                         &s_spiffsWorkBuf[0],
102:                         &s_spiffsFds[0], s_spiffsFds.size(),
103:                         &s_spiffsCache[0], s_spiffsCache.size(),
104:                         NULL);
105: }
