506: /**
507:  * @brief Unpack action.
508:  * @return 0 success, 1 error
509:  *
510:  * @author Pascal Gollor (http://www.pgollor.de/cms/)
511:  */
512: int actionUnpack(void)
513: {
514:     int ret = 0;
515: 
516:     // open spiffs image
517:     FILE* fdsrc = fopen(s_imageName.c_str(), "rb");
518:     if (!fdsrc) {
519:         std::cerr << "error: failed to open image file" << std::endl;
520:         return 1;
521:     }
522: 
523:     if (s_imageSize == 0) {
524:         s_imageSize = getFileSize(fdsrc);
525:     }
526: 
527:     int err = checkArgs();
528:     if (err != 0) {
529:         return err;
530:     }
531: 
532:     s_flashmem.resize(s_imageSize, 0xff);
533: 
534:     // read content into s_flashmem
535:     fread(&s_flashmem[0], 4, s_flashmem.size() / 4, fdsrc);
536: 
537:     // close file handle
538:     fclose(fdsrc);
539: 
540:     // mount file system
541:     if (!spiffsMount()) {
542:         std::cerr << "error: failed to mount image" << std::endl;
543:         return 1;
544:     }
545: 
546:     // unpack files
547:     if (! unpackFiles(s_dirName)) {
548:         ret = 1;
549:     }
550: 
551:     // unmount file system
552:     spiffsUnmount();
553: 
554:     return ret;
555: }
